CREATE OR REPLACE FUNCTION public.units_guard_lineage()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW."replacesUnitId" IS NOT DISTINCT FROM OLD."replacesUnitId" THEN RETURN NEW; END IF;
    IF OLD."replacesUnitId" IS NOT NULL THEN
      RAISE EXCEPTION 'equipment predecessor history cannot change'
        USING ERRCODE = 'check_violation', CONSTRAINT = 'units_lineage_immutable';
    END IF;
  END IF;
  IF NEW."replacesUnitId" IS NULL OR NEW."replacesUnitId" = NEW."id" THEN RETURN NEW; END IF;
  -- Repeatable-read snapshots cannot see an edge committed while waiting on the mutex.
  -- Mutation callers use the repository's default READ COMMITTED transaction.
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'new equipment predecessor links require a READ COMMITTED transaction'
      USING ERRCODE = 'check_violation', CONSTRAINT = 'units_lineage_isolation';
  END IF;
  PERFORM pg_advisory_xact_lock(18461029, 1);
  IF EXISTS (
    WITH RECURSIVE ancestors AS (
      SELECT "id", "replacesUnitId" FROM "units" WHERE "id" = NEW."replacesUnitId"
      UNION
      SELECT u."id", u."replacesUnitId" FROM "units" u JOIN ancestors a ON u."id" = a."replacesUnitId"
    ) SELECT 1 FROM ancestors WHERE "id" = NEW."id" OR "replacesUnitId" = NEW."id"
  ) THEN
    RAISE EXCEPTION 'equipment predecessor history cannot contain a cycle'
      USING ERRCODE = 'check_violation', CONSTRAINT = 'units_lineage_acyclic';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.quote_lines_preserve_sent_terms()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE parent_status "QuoteStatus";
BEGIN
  SELECT "status" INTO parent_status FROM "quotes" WHERE "id" = CASE WHEN TG_OP = 'DELETE' THEN OLD."quoteId" ELSE NEW."quoteId" END FOR SHARE;
  IF parent_status <> 'DRAFT' THEN
    RAISE EXCEPTION 'violates check constraint "quote_lines_frozen_terms"' USING ERRCODE = '23514', CONSTRAINT = 'quote_lines_frozen_terms';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW."quoteId" <> OLD."quoteId" THEN
    RAISE EXCEPTION 'violates check constraint "quote_lines_frozen_terms"' USING ERRCODE = '23514', CONSTRAINT = 'quote_lines_frozen_terms';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.quotes_preserve_frozen_terms()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW."status" <> 'DRAFT' OR NEW."version" <> 1 THEN
      RAISE EXCEPTION 'violates check constraint "quotes_frozen_terms"' USING ERRCODE = '23514', CONSTRAINT = 'quotes_frozen_terms';
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' THEN
    IF OLD."status" <> 'DRAFT' THEN
      RAISE EXCEPTION 'violates check constraint "quotes_frozen_terms"' USING ERRCODE = '23514', CONSTRAINT = 'quotes_frozen_terms';
    END IF;
    RETURN OLD;
  END IF;
  IF ROW(OLD."id", OLD."enquiryId", OLD."surveyId", OLD."packageId", OLD."customerId", OLD."revision", OLD."supersedesQuoteId", OLD."revisionReason",
      OLD."customerSnapshot", OLD."packageSnapshot", OLD."hardwarePrice", OLD."installationPrice", OLD."totalPrice", OLD."createdById", OLD."createdAt")
    IS DISTINCT FROM ROW(NEW."id", NEW."enquiryId", NEW."surveyId", NEW."packageId", NEW."customerId", NEW."revision", NEW."supersedesQuoteId", NEW."revisionReason",
      NEW."customerSnapshot", NEW."packageSnapshot", NEW."hardwarePrice", NEW."installationPrice", NEW."totalPrice", NEW."createdById", NEW."createdAt")
    OR NEW."version" <> OLD."version" + 1
    OR NOT ((OLD."status" = 'DRAFT' AND NEW."status" = 'SENT') OR (OLD."status" = 'SENT' AND NEW."status" IN ('ACCEPTED', 'REJECTED')))
    OR (OLD."status" = 'SENT' AND ROW(OLD."sentAt", OLD."sentById", OLD."sentChannel") IS DISTINCT FROM ROW(NEW."sentAt", NEW."sentById", NEW."sentChannel"))
  THEN
    RAISE EXCEPTION 'violates check constraint "quotes_frozen_terms"' USING ERRCODE = '23514', CONSTRAINT = 'quotes_frozen_terms';
  END IF;
  IF NEW."status" = 'SENT' THEN
    IF (SELECT count(*) FROM "quote_lines" WHERE "quoteId" = NEW."id" AND "kind" = 'PACKAGE' AND "lineTotal" = NEW."hardwarePrice") <> 1
      OR (SELECT count(*) FROM "quote_lines" WHERE "quoteId" = NEW."id" AND "kind" = 'SERVICE' AND "lineTotal" = NEW."installationPrice") <> 1
      OR EXISTS (SELECT 1 FROM unnest(ARRAY['PANEL','INVERTER','CHARGE_CONTROLLER','MOUNTING','WIRING_BOX','SWITCHGEAR','CABLE','EARTHING','CONNECTOR']) AS required(category)
        WHERE NOT EXISTS (SELECT 1 FROM "quote_lines" line WHERE line."quoteId" = NEW."id" AND line."kind" = 'COMPONENT' AND line."productSnapshot"->>'category' = required.category))
      OR ((NEW."packageSnapshot"->>'systemType' = 'OFF_GRID') IS DISTINCT FROM EXISTS (
        SELECT 1 FROM "quote_lines" WHERE "quoteId" = NEW."id" AND "kind" = 'COMPONENT' AND "productSnapshot"->>'category' = 'BATTERY'))
    THEN
      RAISE EXCEPTION 'violates check constraint "quotes_complete_terms"' USING ERRCODE = '23514', CONSTRAINT = 'quotes_complete_terms';
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.allocations_check_source()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  sold RECORD;
  unit_product uuid;
BEGIN
  IF NEW."status" <> 'RESERVED' THEN
    RAISE EXCEPTION 'an allocation starts as reserved' USING ERRCODE = 'restrict_violation';
  END IF;
  SELECT ql."kind", ql."productId", p."trackingMode" INTO sold
  FROM "quote_lines" ql
  JOIN "orders" o ON o."quoteId" = ql."quoteId"
  JOIN "jobs" j ON j."orderId" = o."id"
  JOIN "products" p ON p."id" = ql."productId"
  WHERE ql."id" = NEW."quoteLineId" AND j."id" = NEW."jobId";
  IF NOT FOUND OR sold."kind" <> 'COMPONENT' OR sold."productId" <> NEW."productId" THEN
    RAISE EXCEPTION 'an allocation must match a component sold on its job''s order' USING ERRCODE = 'restrict_violation';
  END IF;
  IF (sold."trackingMode" = 'SERIALIZED') <> (NEW."unitId" IS NOT NULL) THEN
    RAISE EXCEPTION 'serialized stock is allocated by unit, and bulk stock by quantity' USING ERRCODE = 'restrict_violation';
  END IF;
  IF NEW."unitId" IS NOT NULL THEN
    SELECT "productId" INTO unit_product FROM "units" WHERE "id" = NEW."unitId";
    IF unit_product IS DISTINCT FROM NEW."productId" THEN
      RAISE EXCEPTION 'an allocated unit must be the sold product' USING ERRCODE = 'restrict_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.allocations_freeze_identity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' OR NEW."jobId" <> OLD."jobId" OR NEW."quoteLineId" IS DISTINCT FROM OLD."quoteLineId" OR NEW."productId" <> OLD."productId"
    OR NEW."unitId" IS DISTINCT FROM OLD."unitId" OR NEW."locationId" <> OLD."locationId" OR NEW."quantity" <> OLD."quantity"
    OR NEW."actorId" <> OLD."actorId" OR OLD."status" = 'RELEASED' THEN
    RAISE EXCEPTION 'an allocation''s identity cannot change' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.stock_document_line_units_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  parent RECORD;
BEGIN
  FOR parent IN
    SELECT d."status" FROM "stock_documents" d JOIN "stock_document_lines" l ON l."documentId" = d."id"
    WHERE l."id" IN (CASE WHEN TG_OP <> 'INSERT' THEN OLD."lineId" END, CASE WHEN TG_OP <> 'DELETE' THEN NEW."lineId" END)
    ORDER BY d."id" FOR SHARE OF d
  LOOP
    IF parent."status" IN ('DONE', 'CANCELED') THEN
      RAISE EXCEPTION 'units of a closed stock document cannot change' USING ERRCODE = 'restrict_violation';
    END IF;
  END LOOP;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.stock_document_lines_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  old_document uuid;
  new_document uuid;
  parent RECORD;
BEGIN
  IF TG_OP <> 'INSERT' THEN old_document := OLD."documentId"; END IF;
  IF TG_OP <> 'DELETE' THEN new_document := NEW."documentId"; END IF;
  FOR parent IN
    SELECT "id", "kind", "status" FROM "stock_documents" WHERE "id" IN (old_document, new_document) ORDER BY "id" FOR SHARE
  LOOP
    IF parent."status" IN ('DONE', 'CANCELED') THEN
      RAISE EXCEPTION 'lines of a closed stock document cannot change' USING ERRCODE = 'restrict_violation';
    END IF;
    IF parent."id" = new_document AND (parent."kind" = 'ADJUSTMENT') <> (NEW."countedQuantity" IS NOT NULL) THEN
      RAISE EXCEPTION 'only a count line, and every count line, has a counted quantity' USING ERRCODE = 'restrict_violation';
    END IF;
  END LOOP;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.stock_documents_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW."status" <> 'DRAFT' THEN
      RAISE EXCEPTION 'a stock document starts as a draft' USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF OLD."status" IN ('DONE', 'CANCELED') THEN
    RAISE EXCEPTION 'a closed stock document cannot change' USING ERRCODE = 'restrict_violation';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  IF NEW."status" = 'DONE' AND NOT EXISTS (SELECT 1 FROM "stock_document_lines" WHERE "documentId" = NEW."id") THEN
    RAISE EXCEPTION 'a stock document needs lines before validation' USING ERRCODE = 'restrict_violation';
  END IF;
  IF NEW."status" = 'DONE' AND EXISTS (
    SELECT 1 FROM "stock_document_lines" WHERE "documentId" = NEW."id" AND "countedQuantity" IS NOT NULL AND "measuredQuantity" IS NULL
  ) THEN
    RAISE EXCEPTION 'a count must be measured before validation' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.stock_movements_check_source()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  source RECORD;
  expected_from uuid;
  expected_to uuid;
BEGIN
  SELECT d."kind", d."status", COALESCE(d."validatedById", d."actorId") AS "actorId", d."occurredAt", d."fromLocationId", d."toLocationId",
         l."productId", l."quantity", l."countedQuantity", l."measuredQuantity" INTO source
  FROM "stock_document_lines" l JOIN "stock_documents" d ON d."id" = l."documentId"
  WHERE l."id" = NEW."documentLineId";
  IF NOT FOUND OR source."status" <> 'DONE' THEN
    RAISE EXCEPTION 'a stock movement needs a validated document' USING ERRCODE = 'restrict_violation';
  END IF;
  expected_from := source."fromLocationId";
  expected_to := source."toLocationId";
  IF source."kind" = 'ADJUSTMENT' AND source."countedQuantity" < source."measuredQuantity" THEN
    expected_from := source."toLocationId";
    expected_to := NULL;
  END IF;
  IF source."productId" <> NEW."productId" OR source."quantity" <> NEW."quantity" OR source."actorId" <> NEW."actorId"
    OR source."occurredAt" <> NEW."occurredAt" OR expected_from IS DISTINCT FROM NEW."fromLocationId"
    OR expected_to IS DISTINCT FROM NEW."toLocationId" THEN
    RAISE EXCEPTION 'a stock movement must match its document line' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.units_freeze_identity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' OR NEW."productId" <> OLD."productId" OR NEW."manufacturerId" <> OLD."manufacturerId"
    OR NEW."rawSerial" <> OLD."rawSerial" OR NEW."normalizedSerial" <> OLD."normalizedSerial"
    OR NEW."acquisitionCost" <> OLD."acquisitionCost" OR NEW."receiptLineId" <> OLD."receiptLineId" THEN
    RAISE EXCEPTION 'a unit''s identity and cost cannot change' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.allocations_check_release()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF OLD."status" <> 'RELEASED' AND NEW."status" = 'RELEASED' THEN
    IF NEW."releasedAt" IS NULL OR NEW."releasedById" IS NULL OR NEW."releaseReason" IS NULL THEN
      RAISE EXCEPTION 'a new allocation release needs actor, time and reason' USING ERRCODE = 'restrict_violation';
    END IF;
  ELSIF ROW(NEW."releasedAt", NEW."releasedById", NEW."releaseReason")
    IS DISTINCT FROM ROW(OLD."releasedAt", OLD."releasedById", OLD."releaseReason") THEN
    RAISE EXCEPTION 'release evidence is recorded only when releasing an allocation' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.dispatch_scans_check_source()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE source RECORD;
BEGIN
  -- This lock also serializes inserts against the dispatch's version update.
  PERFORM "id" FROM "dispatches" WHERE "id" = NEW."dispatchId" FOR SHARE;
  SELECT d."orderId" AS dispatch_order, j."orderId" AS allocated_order, a."status" AS allocation_status,
    u."status" AS unit_status, u."normalizedSerial", a."createdAt" INTO source
  FROM "allocations" a JOIN "jobs" j ON j."id"=a."jobId" JOIN "units" u ON u."id"=a."unitId"
  JOIN "dispatches" d ON d."id"=NEW."dispatchId" WHERE a."id"=NEW."allocationId" FOR SHARE OF a,u;
  IF NOT FOUND OR source.dispatch_order <> source.allocated_order OR source.allocation_status <> 'RESERVED'
    OR source.unit_status <> 'RESERVED' OR source."normalizedSerial" <> NEW."normalizedSerial"
    OR NEW."recordedAt" < source."createdAt" THEN
    RAISE EXCEPTION 'a dispatch scan must match its reserved equipment and order' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.dispatches_guard_identity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' OR ROW(NEW."id",NEW."orderId",NEW."createdById",NEW."createdAt")
    IS DISTINCT FROM ROW(OLD."id",OLD."orderId",OLD."createdById",OLD."createdAt")
    OR NEW."version" <> OLD."version" + 1 THEN
    RAISE EXCEPTION 'dispatch identity is fixed and changes need the next version' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.installation_time_records_check_overlap()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('time:' || NEW."technicianId"::text, 0));
  IF EXISTS (
    SELECT 1 FROM "installation_time_records"
    WHERE "technicianId" = NEW."technicianId" AND "startedAt" < NEW."finishedAt" AND "finishedAt" > NEW."startedAt"
  ) THEN
    RAISE EXCEPTION 'violates check constraint "installation_time_records_no_overlap"' USING ERRCODE = '23514', CONSTRAINT = 'installation_time_records_no_overlap';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.job_evidence_check_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  job_status "JobStatus";
BEGIN
  SELECT "status" INTO job_status FROM "jobs" WHERE "id" = NEW."jobId" FOR SHARE;
  IF job_status IS DISTINCT FROM 'IN_PROGRESS' THEN
    RAISE EXCEPTION 'evidence can only be added to a job in progress' USING ERRCODE = 'restrict_violation';
  END IF;
  -- Nested, because the time records table has no fileId for this to read.
  IF TG_TABLE_NAME = 'job_photos' THEN
    IF NOT EXISTS (SELECT 1 FROM "files" WHERE "id" = NEW."fileId" AND "contextType" = 'JOB' AND "contextId" = NEW."jobId") THEN
      RAISE EXCEPTION 'a job photo must be a file bound to that job' USING ERRCODE = 'restrict_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.jobs_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW."status" <> OLD."status" AND NOT (
    (OLD."status" = 'SCHEDULED' AND NEW."status" = 'IN_PROGRESS')
    OR (OLD."status" = 'IN_PROGRESS' AND NEW."status" IN ('AWAITING_ACCEPTANCE', 'COMPLETED'))
    OR (OLD."status" = 'AWAITING_ACCEPTANCE' AND NEW."status" = 'COMPLETED')
  ) THEN
    RAISE EXCEPTION 'a job cannot move from % to %', OLD."status", NEW."status" USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD."startedAt" IS NOT NULL AND (NEW."startedAt" IS DISTINCT FROM OLD."startedAt" OR NEW."startedById" IS DISTINCT FROM OLD."startedById") THEN
    RAISE EXCEPTION 'a job''s start cannot change' USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD."status" = 'COMPLETED' AND (NEW."finishedAt" IS DISTINCT FROM OLD."finishedAt" OR NEW."completedAt" IS DISTINCT FROM OLD."completedAt"
    OR NEW."completedById" IS DISTINCT FROM OLD."completedById" OR NEW."installedCapacityKw" IS DISTINCT FROM OLD."installedCapacityKw"
    OR NEW."signatureFileId" IS DISTINCT FROM OLD."signatureFileId" OR NEW."signerName" IS DISTINCT FROM OLD."signerName"
    OR NEW."completedChecks" IS DISTINCT FROM OLD."completedChecks") THEN
    RAISE EXCEPTION 'a completed job''s evidence cannot change' USING ERRCODE = 'restrict_violation';
  END IF;
  IF NEW."status" = 'COMPLETED' AND OLD."status" <> 'COMPLETED' THEN
    IF NOT EXISTS (SELECT 1 FROM "job_photos" WHERE "jobId" = NEW."id") OR NOT EXISTS (SELECT 1 FROM "installation_time_records" WHERE "jobId" = NEW."id") THEN
      RAISE EXCEPTION 'a completed job needs photos and time records' USING ERRCODE = 'restrict_violation';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM "files" WHERE "id" = NEW."signatureFileId" AND "contextType" = 'JOB' AND "contextId" = NEW."id")
      OR EXISTS (SELECT 1 FROM "job_photos" WHERE "fileId" = NEW."signatureFileId") THEN
      RAISE EXCEPTION 'a job''s signature must be its own separate file' USING ERRCODE = 'restrict_violation';
    END IF;
    IF EXISTS (SELECT 1 FROM "installation_time_records" WHERE "jobId" = NEW."id" AND ("startedAt" < NEW."startedAt" OR "finishedAt" > NEW."finishedAt")) THEN
      RAISE EXCEPTION 'time records must fall within the installation' USING ERRCODE = 'restrict_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
